"""Read-only pinned-byte review; writes evidence only under .session/artifacts."""
from pathlib import Path
import hashlib, json, re, subprocess
ROOT = Path.cwd()
OUT = ROOT / '.session/artifacts'
BASE = '486030b461e57ca0f322a17a5b7853e83e9655e3'
OLD = '7435c05c4fd7ddbaafb6f5db9081ad5a4f5db427'
NEW = 'd3c697c375ed7dc880e55ab3cc2219577cd133a5'
def git(*args):
    return subprocess.check_output(['git', *args])
def blob(commit, path):
    return git('show', commit + ':' + path)
def sha(data):
    return hashlib.sha256(data).hexdigest()
def report(n):
    return json.loads((ROOT / f'.session/exports/reports/{n}.json').read_text())
files = ['README.md', 'controls.json', 'input-pins.json', 'method.json', 'review-corrections.json', 'verification.json', 'verify_method.py']
expected = dict((name, digest) for digest, name in re.findall(r'([0-9a-f]{64})  ([\w.-]+)', report(489)['body']))
hashes = {}
for name in files:
    path = 'benchmark/writing/' + name
    values = {'accepted': sha(blob(NEW, path)), 'HEAD': sha(blob('HEAD', path)), 'worktree': sha((ROOT / path).read_bytes()), 'report489': expected[name]}
    assert len(set(values.values())) == 1, (name, values)
    hashes[name] = values
pins = json.loads(blob(NEW, 'benchmark/writing/input-pins.json'))
old_pins = json.loads(blob(OLD, 'benchmark/writing/input-pins.json'))
assert pins['baseline_commit'] == BASE
assert pins['baseline_tree'] == git('rev-parse', BASE + '^{tree}').decode().strip()
changed_pin_fields = [k for k in pins if pins[k] != old_pins[k]]
assert sorted(changed_pin_fields) == ['baseline_commit', 'baseline_tree']
protected = []
for path, expected_hash in pins['protected_inputs_sha256'].items():
    values = {c: sha(blob(c, path)) for c in (BASE, OLD, NEW, 'HEAD')}
    values['worktree'] = sha((ROOT / path).read_bytes())
    assert set(values.values()) == {expected_hash}, (path, values)
    protected.append({'path': path, 'sha256': expected_hash, 'matches_baseline_old_accepted_HEAD_worktree': True})
index = json.loads(blob(BASE, 'benchmark/preparation.json'))
refs = []
def walk(value):
    if isinstance(value, dict):
        if isinstance(value.get('path'), str) and isinstance(value.get('sha256'), str):
            refs.append((value['path'], value['sha256']))
        for child in value.values(): walk(child)
    elif isinstance(value, list):
        for child in value: walk(child)
walk(index)
assert len(refs) == 74 and len(set(refs)) == 56
for path, digest in set(refs):
    assert pins['protected_inputs_sha256'][path] == digest
    assert sha(blob(BASE, path)) == digest
assert len(protected) == 62
old_controls = json.loads(blob(OLD, 'benchmark/writing/controls.json'))
controls = json.loads(blob(NEW, 'benchmark/writing/controls.json'))
old_rows = old_controls.pop('rejecting_controls')
rows = controls.pop('rejecting_controls')
assert controls == old_controls and rows[:35] == old_rows and len(old_rows) == 35 and len(rows) == 44
assert len(set(r['id'] for r in rows)) == 44
assert blob(OLD, 'benchmark/writing/method.json') == blob(NEW, 'benchmark/writing/method.json')
# Independently compare the raw JSON object span of every original control.
def raw_rows(raw):
    text = raw.decode(); pos = text.index('[', text.index('"rejecting_controls"')) + 1
    decoder = json.JSONDecoder(); found = []
    while True:
        while text[pos].isspace() or text[pos] == ',': pos += 1
        if text[pos] == ']': return found
        _, length = decoder.raw_decode(text[pos:]); found.append(text[pos:pos + length]); pos += length
assert raw_rows(blob(OLD, 'benchmark/writing/controls.json')) == raw_rows(blob(NEW, 'benchmark/writing/controls.json'))[:35]
identities = {c: git('rev-parse', c, c + '^{tree}').decode().splitlines() for c in (BASE, OLD, NEW, 'HEAD')}
checkpoint = subprocess.run(['git', 'rev-parse', '--verify', 'f86939aed871aee754a096d9b378870ebb39d095^{tree}'], capture_output=True, text=True)
changes = {label: git('diff', '--name-status', left, right).decode().splitlines() for label, left, right in [('original_to_accepted', OLD, NEW), ('accepted_to_HEAD', NEW, 'HEAD'), ('baseline_to_accepted', BASE, NEW)]}
full_diff = git('diff', '--no-ext-diff', OLD, NEW, '--', 'benchmark/writing/')
(OUT / 'writing.diff').write_bytes(full_diff)
evidence = {'identities': identities, 'author_checkpoint_tree_resolution': {'exit': checkpoint.returncode, 'stdout': checkpoint.stdout.strip(), 'stderr': checkpoint.stderr.strip()}, 'seven_hashes': hashes, 'changed_paths': changes, 'changed_input_pin_fields': changed_pin_fields, 'protected': protected, 'index_references': len(refs), 'unique_index_pins': len(set(refs)), 'index_pins': [dict(path=p, sha256=h) for p,h in sorted(set(refs))], 'method_unchanged': True, 'original_controls_raw_objects_unchanged': 35, 'added_controls': rows[35:]}
for n in (481,485):
    info = json.loads(blob(NEW, 'benchmark/writing/review-corrections.json'))['reports'][str(n)]
    exported = ROOT / f'.session/exports/reports/{n}.json'
    evidence.setdefault('report_provenance', {})[str(n)] = {'source_matches': info['source'] == report(n)['source'], 'snapshot_matches': info['snapshot'] == report(n)['snapshot'], 'actual_export_sha256': sha(exported.read_bytes()), 'authored_export_sha256': info['export_sha256']}
(OUT / 'snapshot.json').write_text(json.dumps(evidence, indent=2) + '\n')
print(json.dumps({'identities': identities, 'seven_hashes_match_report489': len(hashes), 'protected_hashes_match': len(protected), 'index_references': len(refs), 'unique_index_pins': len(set(refs)), 'method_unchanged': True, 'old_controls_raw_unchanged': 35, 'added_controls': len(rows)-35, 'pin_fields_changed': changed_pin_fields, 'report_provenance': evidence['report_provenance']}, sort_keys=True))

